import sys
from math import factorial
from collections import Counter

def rank_of_number(N):
    count = Counter(N)
    total_permutations = factorial(len(N))
    for digit in sorted(count):
        for d in sorted(count):
            if d < digit:
                total_permutations -= factorial(len(N) - 1) // prod(factorial(count[d]) for d in count)
        count[digit] -= 1
        if count[digit] == 0:
            del count[digit]
        if not count:
            break
    return total_permutations + 1

def prod(iterable):
    result = 1
    for x in iterable:
        result *= x
    return result

input = sys.stdin.read().split()
T = int(input[0])
test_cases = input[1:]
ranks = [rank_of_number(N) for N in test_cases]
print('\n'.join(map(str, ranks)))
